                 //         "amount":"0.249825",
                 //         "amountRemaining":"0",
                 //         "onHold":"0",
                 //         "onHoldCurrency":"ETH",
                 //         "filledAmount":"0.249825",
                 //         "filledAmountQuote":"45.84038925",
                 //         "feePaid":"0.12038925",
